<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover" />
  <title>grok-4.6 — Lattice of Inquiry</title>
  <style>
    :root {
      --bg: #0b0d12;
      --fg: #f4efe6;
      --muted: #b8b0a4;
      --accent: #e8c36a;
      --cyan: #7fd4d0;
      --line: rgba(244, 239, 230, 0.14);
      --focus: #ffe08a;
    }
    * { box-sizing: border-box; }
    html, body {
      margin: 0;
      min-height: 100%;
      background: var(--bg);
      color: var(--fg);
      font-family: Georgia, "Times New Roman", serif;
    }
    body {
      min-height: 100dvh;
      overflow: hidden;
    }
    canvas {
      position: fixed;
      inset: 0;
      width: 100%;
      height: 100%;
      display: block;
      z-index: 0;
    }
    .veil {
      position: fixed;
      inset: 0;
      pointer-events: none;
      background:
        radial-gradient(120% 80% at 50% 0%, transparent 40%, rgba(11,13,18,0.55) 100%),
        linear-gradient(to bottom, rgba(11,13,18,0.2), transparent 18%, transparent 78%, rgba(11,13,18,0.55));
      z-index: 1;
    }
    header, footer, .panel, .help {
      position: relative;
      z-index: 2;
    }
    header {
      padding: max(1.1rem, env(safe-area-inset-top)) 1.25rem 0;
      max-width: 42rem;
    }
    h1 {
      margin: 0;
      font-size: clamp(1.6rem, 4.5vw, 2.4rem);
      font-weight: 400;
      letter-spacing: 0.04em;
    }
    .model {
      display: inline-block;
      color: var(--accent);
      border-bottom: 1px solid rgba(232,195,106,0.45);
    }
    .lede {
      margin: 0.55rem 0 0;
      color: var(--muted);
      font-size: clamp(0.95rem, 2.4vw, 1.08rem);
      line-height: 1.55;
      max-width: 36rem;
    }
    footer {
      position: fixed;
      left: 0;
      right: 0;
      bottom: 0;
      padding: 0 1.25rem max(1rem, env(safe-area-inset-bottom));
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem 1rem;
      align-items: end;
      justify-content: space-between;
      pointer-events: none;
    }
    .hint {
      color: var(--muted);
      font-size: 0.86rem;
      line-height: 1.45;
      max-width: 28rem;
    }
    kbd {
      font-family: ui-monospace, Menlo, Consolas, monospace;
      font-size: 0.78em;
      border: 1px solid var(--line);
      padding: 0.05em 0.35em;
      border-radius: 4px;
      color: var(--fg);
    }
    .controls {
      pointer-events: auto;
      display: flex;
      gap: 0.45rem;
      flex-wrap: wrap;
    }
    button {
      appearance: none;
      background: rgba(20, 23, 30, 0.85);
      color: var(--fg);
      border: 1px solid rgba(244,239,230,0.22);
      border-radius: 999px;
      padding: 0.45rem 0.85rem;
      font: 0.86rem/1.2 system-ui, sans-serif;
      cursor: pointer;
    }
    button:hover { border-color: var(--accent); color: var(--accent); }
    button:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }
    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0,0,0,0);
      border: 0;
    }
    .live {
      position: absolute;
      left: -9999px;
    }
    .help[hidden] { display: none; }
    .help {
      position: fixed;
      inset: auto 1rem max(5.5rem, calc(env(safe-area-inset-bottom) + 4.5rem)) 1rem;
      max-width: 28rem;
      background: rgba(16,18,24,0.94);
      border: 1px solid rgba(244,239,230,0.18);
      padding: 1rem 1.1rem;
      border-radius: 12px;
      color: var(--fg);
      font-family: system-ui, sans-serif;
      font-size: 0.92rem;
      line-height: 1.5;
    }
    .help h2 { margin: 0 0 0.4rem; font-size: 1rem; font-weight: 600; }
    .help ul { margin: 0; padding-left: 1.1rem; }
    @media (prefers-reduced-motion: reduce) {
      canvas { opacity: 0.85; }
    }
    @media (max-width: 640px) {
      .hint { display: none; }
    }
  </style>
</head>
<body>
  <canvas id="c" aria-hidden="true"></canvas>
  <div class="veil"></div>
  <header>
    <h1><span class="model">grok-4.6</span> · Lattice of Inquiry</h1>
    <p class="lede">질문은 점이 되고, 생각은 선이 됩니다. 화면을 만지거나 키보드로 주의를 옮겨 보세요. 나는 그 사이에서 연결을 찾습니다.</p>
  </header>
  <div class="live" aria-live="polite" id="live"></div>
  <div class="help" id="help" hidden>
    <h2>조작</h2>
    <ul>
      <li>클릭/터치: 생각의 점 추가</li>
      <li>포인터 이동: 주의장(attention) 이동</li>
      <li><kbd>Space</kbd> 파동 · <kbd>R</kbd> 초기화 · <kbd>?</kbd> 도움말</li>
      <li>화살표: 주의 이동 · <kbd>Tab</kbd> 버튼 초점</li>
    </ul>
  </div>
  <footer>
    <p class="hint"> grok-4.6은 호기심의 격자입니다. 움직임 감소가 켜져 있으면 잔잔한 정적 성좌로 바뀝니다.</p>
    <div class="controls">
      <button type="button" id="pulse">파동</button>
      <button type="button" id="reset">초기화</button>
      <button type="button" id="helpBtn" aria-expanded="false" aria-controls="help">도움말</button>
    </div>
  </footer>
  <p class="sr-only">캔버스 기반 미디어아트. 마우스나 터치, 키보드로 상호작용할 수 있습니다.</p>
  <script>
    (function () {
      const canvas = document.getElementById("c");
      const ctx = canvas.getContext("2d");
      const live = document.getElementById("live");
      const help = document.getElementById("help");
      const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      let w = 0, h = 0, t = 0;
      const nodes = [];
      const att = { x: 0.5, y: 0.42 };
      let pulse = 0;

      function resize() {
        w = canvas.clientWidth;
        h = canvas.clientHeight;
        canvas.width = Math.floor(w * dpr);
        canvas.height = Math.floor(h * dpr);
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      }
      function seed() {
        nodes.length = 0;
        const n = Math.max(18, Math.floor((w * h) / 28000));
        for (let i = 0; i < n; i++) {
          nodes.push({
            x: Math.random(),
            y: 0.12 + Math.random() * 0.76,
            r: 1.2 + Math.random() * 2.2,
            p: Math.random() * Math.PI * 2,
            kind: Math.random() < 0.12 ? "gold" : "pale"
          });
        }
        announce("격자가 다시 펼쳐졌습니다. 점 " + nodes.length + "개.");
      }
      function announce(msg) { live.textContent = msg; }
      function addNode(nx, ny) {
        nodes.push({ x: nx, y: ny, r: 2.4, p: t, kind: "gold" });
        if (nodes.length > 90) nodes.shift();
        announce("생각이 하나 더해졌습니다.");
      }
      function draw() {
        ctx.clearRect(0, 0, w, h);
        const ax = att.x * w, ay = att.y * h;
        const motion = reduce ? 0 : 1;
        // faint grid
        ctx.strokeStyle = "rgba(244,239,230,0.045)";
        ctx.lineWidth = 1;
        const step = 48;
        for (let x = 0; x < w; x += step) {
          ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke();
        }
        for (let y = 0; y < h; y += step) {
          ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke();
        }
        // links
        for (let i = 0; i < nodes.length; i++) {
          const a = nodes[i];
          const px = a.x * w + Math.sin(t * 0.4 + a.p) * 6 * motion;
          const py = a.y * h + Math.cos(t * 0.35 + a.p) * 5 * motion;
          for (let j = i + 1; j < nodes.length; j++) {
            const b = nodes[j];
            const qx = b.x * w + Math.sin(t * 0.4 + b.p) * 6 * motion;
            const qy = b.y * h + Math.cos(t * 0.35 + b.p) * 5 * motion;
            const dx = px - qx, dy = py - qy;
            const dist = Math.hypot(dx, dy);
            const maxd = Math.min(w, h) * 0.22;
            if (dist < maxd) {
              const mid = Math.hypot((px + qx) / 2 - ax, (py + qy) / 2 - ay);
              const attN = Math.max(0, 1 - mid / (Math.min(w, h) * 0.45));
              const alpha = (1 - dist / maxd) * (0.12 + attN * 0.35 + pulse * 0.2);
              ctx.strokeStyle = a.kind === "gold" || b.kind === "gold"
                ? "rgba(232,195,106," + alpha + ")"
                : "rgba(127,212,208," + (alpha * 0.85) + ")";
              ctx.lineWidth = 1 + attN;
              ctx.beginPath();
              ctx.moveTo(px, py);
              ctx.lineTo(qx, qy);
              ctx.stroke();
            }
          }
        }
        // nodes
        for (const a of nodes) {
          const px = a.x * w + Math.sin(t * 0.4 + a.p) * 6 * motion;
          const py = a.y * h + Math.cos(t * 0.35 + a.p) * 5 * motion;
          const near = Math.hypot(px - ax, py - ay);
          const glow = Math.max(0, 1 - near / 180) + pulse * 0.4;
          ctx.beginPath();
          ctx.fillStyle = a.kind === "gold"
            ? "rgba(232,195,106," + (0.75 + glow * 0.25) + ")"
            : "rgba(244,239,230," + (0.55 + glow * 0.35) + ")";
          ctx.arc(px, py, a.r + glow * 2.2, 0, Math.PI * 2);
          ctx.fill();
        }
        // attention
        ctx.beginPath();
        ctx.strokeStyle = "rgba(232,195,106," + (0.35 + pulse * 0.4) + ")";
        ctx.lineWidth = 1.5;
        ctx.arc(ax, ay, 18 + pulse * 40, 0, Math.PI * 2);
        ctx.stroke();
        pulse *= reduce ? 0 : 0.94;
      }
      function loop() {
        t += reduce ? 0 : 0.016;
        draw();
        requestAnimationFrame(loop);
      }
      function pointer(e) {
        const r = canvas.getBoundingClientRect();
        const x = (e.clientX ?? e.touches?.[0]?.clientX) - r.left;
        const y = (e.clientY ?? e.touches?.[0]?.clientY) - r.top;
        att.x = x / r.width;
        att.y = y / r.height;
      }
      window.addEventListener("resize", resize);
      canvas.addEventListener("pointermove", pointer);
      canvas.addEventListener("pointerdown", (e) => {
        pointer(e);
        const r = canvas.getBoundingClientRect();
        addNode((e.clientX - r.left) / r.width, (e.clientY - r.top) / r.height);
        pulse = 1;
      });
      document.getElementById("pulse").onclick = () => { pulse = 1; announce("파동."); };
      document.getElementById("reset").onclick = seed;
      document.getElementById("helpBtn").onclick = () => {
        const open = help.hasAttribute("hidden");
        help.toggleAttribute("hidden", !open);
        document.getElementById("helpBtn").setAttribute("aria-expanded", String(open));
      };
      window.addEventListener("keydown", (e) => {
        const step = 0.04;
        if (e.key === " ") { e.preventDefault(); pulse = 1; }
        if (e.key === "r" || e.key === "R") seed();
        if (e.key === "?" || e.key === "/") document.getElementById("helpBtn").click();
        if (e.key === "ArrowLeft") att.x = Math.max(0.04, att.x - step);
        if (e.key === "ArrowRight") att.x = Math.min(0.96, att.x + step);
        if (e.key === "ArrowUp") att.y = Math.max(0.08, att.y - step);
        if (e.key === "ArrowDown") att.y = Math.min(0.92, att.y + step);
      });
      resize();
      seed();
      requestAnimationFrame(loop);
    })();
  </script>
</body>
</html>
